import {goalDefinitions,validateGoals,filterProducts,goalText} from './logic.js?v=inline8';
const $=id=>document.getElementById(id), keys=Object.keys(goalDefinitions);
const stories={calories:{category:'calories',query:'popcorn',goal:'calories',value:150,title:'Compare calories in a serving of popcorn.',intro:'Choose a calorie ceiling for individual-serving popcorn. Keep the amount in each labeled pack beside its calories, then compare equal-weight amounts when pack sizes differ.',scope:'Individual-serving popcorn.',goalTitle:'Your calorie ceiling'},protein:{category:'protein',query:'bars',goal:'protein',value:10,title:'Find protein bars that meet your number.',intro:'Choose a minimum protein amount. Protein grams lead beneath each bar description, with serving weight and source facts close at hand.',scope:'Protein bars.',goalTitle:'Your protein minimum'},fiber:{category:'fiber',query:'bars',goal:'fiber',value:6,title:'Find fiber products with a clear serving basis.',intro:'Choose a minimum fiber amount. See fiber grams directly beneath each description and compare bar servings without confusing the box with a serving.',scope:'Fiber bars and brownies.',goalTitle:'Your fiber minimum'}};
const requestedStory=new URLSearchParams(location.search).get('story');
const storyKey=Object.hasOwn(stories,requestedStory)?requestedStory:'protein',story=stories[storyKey];
let currentStep=1;
function showStep(n,focus=true){if(!story)return;currentStep=n;for(let i=1;i<=3;i++)$('walk-step-'+i).hidden=i!==n;document.querySelectorAll('.step-nav [data-step]').forEach(b=>{if(Number(b.dataset.step)===n)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});const shared=$('inline-shopping');if(shared)shared.hidden=n===1;document.body.classList.toggle('shopping-mode',n!==1);$('search-form').hidden=true;if(focus){$('step-title-'+n).focus({preventScroll:true});if(n!==3)window.scrollTo({top:0,behavior:'instant'});}}
let products=[],original=[],applied={},query=story?.query||'',selected=new Set(),missing=false;
let draft=Object.fromEntries(keys.map(k=>[k,{enabled:false,value:''}]));
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brands=()=>Array.from(document.querySelectorAll('.brand-filter:checked')).flatMap(i=>i.value.split(','));
function status(){let r=validateGoals(draft);$('draft-status').textContent=r.valid&&JSON.stringify(r.values)===JSON.stringify(applied)?Object.keys(applied).length?'Goals applied':'No goals applied':'Changes not applied';}
function clear(k){$(k).removeAttribute('aria-invalid');$(k+'-error').hidden=true;$(k).setAttribute('aria-describedby','goal-basis');$('form-error').hidden=true;}
function sync(){keys.forEach(k=>{$('enable-'+k).checked=draft[k].enabled;$(k+'-field').hidden=k===story.goal?false:!draft[k].enabled;$(k).disabled=k===story.goal?false:!draft[k].enabled;$(k).value=draft[k].value;clear(k);});status();}
function nutrient(p,k){let v=p[goalDefinitions[k].field];return typeof v==='number'&&Number.isFinite(v)?`${v} <small>${goalDefinitions[k].unit}</small>`:p.conflicting?.includes(k)?'Conflict':'Unknown';}
function reviewContext(p){let r=p.amazon_review;if(r&&Number.isFinite(r.rating)&&r.rating>=0&&r.rating<=5&&Number.isInteger(r.count)&&r.count>=0&&r.url&&r.checked_at)return `<p class="review-context"><span class="review-stars" aria-hidden="true">★</span> ${r.rating} out of 5 · <a href="${esc(r.url)}" target="_blank" rel="noopener">${r.count.toLocaleString()} ratings ↗</a><small>Rating snapshot</small></p>`;return '<p class="review-context review-placeholder">Customer ratings unavailable<small>No verified rating snapshot for this listing.</small></p>';}
function render(){let shown=filterProducts(products,applied,query,brands()),active=story?[story.goal,...Object.keys(applied).filter(k=>k!==story.goal)]:Object.keys(applied);$('query-title').textContent=query||'all demo products';$('result-count').textContent=`${shown.length} ${shown.length===1?'result':'results'} in this demo`;
$('applied-chips').replaceChildren();for(let [k,v]of Object.entries(applied)){let b=document.createElement('button');b.type='button';b.textContent=goalText(k,v)+' ×';b.setAttribute('aria-label','Remove '+goalText(k,v)+' goal');b.onclick=()=>{delete applied[k];draft[k].enabled=false;sync();render();$('enable-'+k).focus();};$('applied-chips').append(b);}
$('products').innerHTML=shown.map(p=>`<article class="product" aria-label="${esc(p.name)}"><div class="product-image"><img src="assets/${p.image}" alt="${esc(p.name)} source package" width="240" height="240"></div><div class="product-copy"><p class="product-brand">${p.brand}</p><h3>${esc(p.name)}</h3><p class="product-size">${esc(p.pack)}</p>${reviewContext(p)}<div class="nutrition"><p>Per ${p.serving} · not the full package</p>${active.length?`<dl>${active.map(k=>`<div><dt>${goalDefinitions[k].label}</dt><dd>${nutrient(p,k)}</dd></div>`).join('')}</dl>`:'<p>Select a goal to show its numeric fact here.</p>'}<a href="${p.label_url}" target="_blank" rel="noopener">Fact source ↗</a></div><p class="match-note">${Object.keys(applied).length?'Matches all applied goals':'No numeric goal applied.'}</p>${p.warning?`<p class="limitation">${esc(p.warning)}</p>`:''}<button class="source-button" data-label="${p.id}">View facts</button><button class="compare-button" data-compare="${p.id}" aria-pressed="${selected.has(p.id)}">${selected.has(p.id)?'Remove comparison':'Compare'}</button></div></article>`).join('');
$('empty').hidden=!!shown.length;if(!shown.length)$('empty-reason').textContent=active.length?'No example meets every applied goal. Unknown or conflicting required values are excluded. Try lowering a minimum or removing a goal.':'No example matches this search or brand selection. Clear the search or uncheck brands.';
document.querySelectorAll('[data-label]').forEach(b=>b.onclick=()=>facts(b.dataset.label));document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{selected.has(b.dataset.compare)?selected.delete(b.dataset.compare):selected.add(b.dataset.compare);render();});comparison();status();}
function comparison(){let ps=products.filter(p=>selected.has(p.id));$('comparison').hidden=!ps.length;if(!ps.length)return;let basis=$('compare-basis')?.value||'serving';$('comparison').innerHTML=`<h3>Compare nutrition</h3><p class="small">${ps.length===1?'Select another example to compare.':ps.length+' examples selected.'}</p><label for="compare-basis">Comparison basis </label><select id="compare-basis"><option value="serving">Per labeled serving</option><option value="100">Per 100 g</option></select><table><caption>${basis==='100'?'Amounts per 100 g (calculated)':'Amounts per labeled serving'}</caption><thead><tr><th scope="col">Fact</th>${ps.map(p=>`<th scope="col">${esc(p.name)}</th>`).join('')}</tr></thead><tbody><tr><th scope="row">Package serving (reference)</th>${ps.map(p=>`<td>${p.serving}</td>`).join('')}</tr>${keys.map(k=>`<tr><th scope="row">${goalDefinitions[k].label}</th>${ps.map(p=>`<td>${typeof p[goalDefinitions[k].field]==='number'?`${basis==='100'?+(p[goalDefinitions[k].field]*100/p.weight_g).toFixed(1):p[goalDefinitions[k].field]} ${goalDefinitions[k].unit}`:p.conflicting?.includes(k)?'Conflicting':'Unknown'}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="small">Per 100 g is a calculated equal-weight comparison, not a serving suggestion. Package servings are different sizes.</p>`;$('compare-basis').value=basis;$('compare-basis').onchange=comparison;}
function facts(id){let p=products.find(p=>p.id===id);$('label-title').textContent=p.name;$('label-serving').textContent='Per '+p.serving;$('label-facts').innerHTML=keys.map(k=>`<div><dt>${goalDefinitions[k].label}</dt><dd>${nutrient(p,k)}</dd></div>`).join('');$('label-note').textContent=p.note+(p.conflicting?.length?' Scenario: selected nutrient is conflicting and excluded from matching.':'');$('label-source').href=p.label_url;$('label-dialog').showModal();$('close-dialog').focus();}
function reset(){applied={};draft=Object.fromEntries(keys.map(k=>[k,{enabled:false,value:''}]));sync();render();}
keys.forEach(k=>{$('enable-'+k).onchange=e=>{draft[k].enabled=e.target.checked;sync();};$(k).oninput=e=>{draft[k].value=e.target.value;if(k===story.goal){draft[k].enabled=true;$('enable-'+k).checked=true;}clear(k);status();};});
$('goals').onsubmit=e=>{e.preventDefault();let r=validateGoals(draft);keys.forEach(clear);if(!r.valid){Object.entries(r.errors).forEach(([k,msg])=>{$(k).setAttribute('aria-invalid','true');$(k).setAttribute('aria-describedby',k+'-error goal-basis');$(k+'-error').textContent=msg;$(k+'-error').hidden=false;});$('form-error').textContent='Enter valid values. Applied results have not changed.';$('form-error').hidden=false;$(Object.keys(r.errors)[0]).focus();return;}applied={...r.values};render();showStep(3,false);};
$('reset').onclick=reset;$('empty-reset').onclick=()=>{reset();$('enable-'+story.goal).focus();};$('search-form').onsubmit=e=>{e.preventDefault();query=$('search').value.trim();render();};document.querySelectorAll('.brand-filter').forEach(i=>i.onchange=render);$('close-dialog').onclick=()=>$('label-dialog').close();
function example(){reset();query=story.query;$('search').value=query;document.querySelectorAll('.brand-filter').forEach(i=>i.checked=false);draft[story.goal]={enabled:true,value:String(story.value)};applied={[story.goal]:story.value};sync();render();}
$('story-example').onclick=example;
$('missing-demo').onclick=()=>{missing=true;products=original.map(p=>({...p,[goalDefinitions[story.goal].field]:p.id===original[0]?.id?null:p[goalDefinitions[story.goal].field]}));$('missing-demo').textContent='Scenario active: first example has an unknown '+goalDefinitions[story.goal].label.toLowerCase();render();};$('reload-demo').onclick=()=>{missing=false;products=original.map(p=>({...p}));$('missing-demo').textContent='Try missing-data scenario';render();};
if(story){$('landing').hidden=true;$('story-content').hidden=false;$('search').value=query;$('story-eyebrow').textContent=storyKey==='calories'?'LOW-CALORIE CHOICES':storyKey==='protein'?'PROTEIN BARS':'FIBER PRODUCTS';$('story-title').textContent=story.title;$('story-intro').textContent='Independent prototype · Regular Amazon retail · No live shopping.';$('story-scope').textContent=story.scope;$('goal-title').textContent=story.goalTitle;document.title='Amazon concept — '+$('story-eyebrow').textContent;let toggles=document.querySelector('.goal-toggles'),optional=document.createElement('details');optional.className='optional-goals';optional.innerHTML='<summary>Optional combined goals</summary>';let group=document.createElement('div');group.className='goal-toggles';for(let k of keys){let label=$('enable-'+k).closest('label');if(k!==story.goal)group.append(label);}toggles.prepend($('enable-'+story.goal).closest('label'));optional.append(group);toggles.after(optional);document.querySelectorAll('.story-nav a').forEach(a=>{if(a.getAttribute('href')==='?story='+storyKey)a.setAttribute('aria-current','page');});
const host=$('story-content'),intro=host.querySelector('.introduction'),shopping=host.querySelector('.shopping'),evidence=$('evidence'),why=host.querySelector('.walkthrough'),validation=host.querySelector('.validation');
host.querySelector('.change-strip').hidden=true;
const nav=document.createElement('nav');nav.className='step-nav';nav.setAttribute('aria-label','Three-step walkthrough');nav.innerHTML='<button data-step="1" aria-current="step">1 Observe</button><button data-step="2">2 Proposed change</button><button data-step="3">3 See results</button><button id="restart-walkthrough">Restart walkthrough</button>';intro.after(nav);
for(let n=1;n<=3;n++){let section=document.createElement('section');section.id='walk-step-'+n;section.className='walk-step';section.hidden=n!==1;section.innerHTML='<p class="eyebrow">STEP '+n+' OF 3</p><h2 tabindex="-1" id="step-title-'+n+'">'+['Observe the current workflow','Review the proposed change','See the results'][n-1]+'</h2>';host.append(section);}
const obs=document.createElement('div');obs.className='observe-summary';obs.innerHTML='<p>Search, check existing nutrition filters, then open a product’s facts to confirm the serving.</p><p class="evidence-scope">'+({protein:'Actual protein-search evidence.',calories:'Actual popcorn-search phone evidence.',fiber:'Actual fiber-bars phone evidence · two-column grid.'}[storyKey])+'</p>';
$('walk-step-1').append(obs,evidence);
const mobile=document.createElement('figure');mobile.className='mobile-before';
const phoneEvidence={protein:{image:'before-mobile-protein-row.svg',alt:'Actual user-supplied Amazon phone protein result row, cropped below header and above cart controls',caption:'Actual supplied phone protein-search row. Selected title text already includes a numeric protein claim. Historical price/rating/delivery text is screenshot evidence only, not a live offer. Header, account, location and cart controls excluded.'},calories:{image:'before-mobile-popcorn-row.svg',alt:'Actual supplied Amazon popcorn search row showing SkinnyPop Original .65 oz 30-count bags',caption:'Actual user-supplied phone screenshot: “popcorn skinny pop” search, SkinnyPop Original .65 oz (30 Count). Received October 8 UTC; capture time unverified. Historical ratings, prices and delivery text are screenshot evidence, not live offers. Header and cart controls cropped out.'},fiber:{image:'before-mobile-fiber-grid.svg',alt:'Actual supplied Amazon fiber bars search two-column grid showing MadeGood and Fiber One Oats and Chocolate',caption:'Actual user-supplied phone screenshot: “fiber bars” search in a two-column grid, including Fiber One Oats & Chocolate. Received October 8 UTC; capture time unverified. Proposed results use compact rows with nutrition beside the image, a layout change from this grid. Historical ratings, prices and delivery text are screenshot evidence, not live offers. Header and cart controls cropped out.'}}[storyKey];
mobile.innerHTML='<img src="assets/'+phoneEvidence.image+'" alt="'+esc(phoneEvidence.alt)+'"><figcaption>'+esc(phoneEvidence.caption)+'</figcaption>';evidence.prepend(mobile);
const evidenceContext=document.createElement('details');evidenceContext.className='context-disclosure';evidenceContext.innerHTML='<summary>'+(storyKey==='protein'?'Desktop evidence, existing tools and scope':'Evidence provenance and scope')+'</summary>';
if(storyKey==='protein'){for(const child of [...evidence.children])if(child!==mobile)evidenceContext.append(child);}else{for(const child of [...evidence.children])if(child!==mobile)child.remove();const note=document.createElement('p');note.className='small';note.textContent='Source: user-supplied '+(storyKey==='calories'?'recorded phone reference':'recorded phone reference')+', received October 8 UTC. No capture URL or timestamp independently established. This is regular Amazon search evidence; Whole Foods/Fresh shopping modules are outside this concept. Existing nutrition filters and Compare were separately observed in protein-search evidence; this category screenshot does not establish its full filter set.';evidenceContext.append(note);}evidence.append(evidenceContext);
const rationale=document.createElement('details');rationale.className='context-disclosure';rationale.innerHTML='<summary>Why this change? Evidence and tradeoffs</summary>';rationale.append(why);
const methods=document.createElement('details');methods.className='context-disclosure';methods.innerHTML='<summary>Methodology, limitations and proposed tests</summary>';methods.append(validation);
const shared=document.createElement('section');shared.id='inline-shopping';shared.hidden=true;host.append(shared);shared.append(shopping,rationale,methods);
const goals=$('goals');goals.classList.add('inline-goals');const advanced=document.createElement('details');advanced.className='advanced-goals';advanced.innerHTML='<summary>More nutrition options</summary>';const advancedContent=document.createElement('div');advancedContent.className='advanced-goal-content';advancedContent.append(toggles,optional);for(const k of keys)if(k!==story.goal)advancedContent.append($(k+'-field'));advanced.append(advancedContent);const mainField=$(story.goal+'-field');goals.querySelector('.goals-heading').hidden=true;goals.querySelector('.goal-fields').append(mainField);const action=goals.querySelector('.goal-actions');action.querySelector('[type=submit]').textContent='Apply';$('goal-basis').textContent='Per labeled serving · all selected goals must match.';shared.append(advanced);advanced.classList.add('context-disclosure');$('draft-status').remove();action.after($('form-error'));const inlineStatus=document.createElement('span');inlineStatus.id='draft-status';inlineStatus.setAttribute('role','status');$('result-count').after(inlineStatus);
$('results').prepend(goals);$('result-count').after($('applied-chips'));const ratingNote=document.createElement('p');ratingNote.className='rating-disclosure';ratingNote.textContent='Amazon listing snapshots; may include variants and may change. Sources checked Oct 8, 2026.';$('products').before(ratingNote);
$('story-example').hidden=true;document.querySelector('.goal-shortcut').hidden=true;$('empty-reset').onclick=()=>{reset();};
$('step-title-2').textContent='Proposed inline filter';$('step-title-3').textContent='Results updated below';
for(let n=1;n<=3;n++){let actions=document.createElement('div');actions.className='step-actions';if(n>1)actions.innerHTML='<button type="button" class="outline" data-step="'+(n-1)+'">← Back</button>';if(n===1)actions.innerHTML+='<button type="button" class="primary" data-step="'+(n+1)+'">'+(n===1?'Next: Proposed change →':'Apply and see results →')+'</button>';$('walk-step-'+n).append(actions);}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{if(b.closest('.step-actions')&&Number(b.dataset.step)===3)$('goals').requestSubmit();else showStep(Number(b.dataset.step));});$('restart-walkthrough').onclick=()=>{products=original.map(p=>({...p}));selected.clear();example();showStep(1);};document.querySelector('.skip').onclick=e=>{e.preventDefault();showStep(1);};document.querySelector('.header-link').onclick=e=>{e.preventDefault();showStep(1);};$('search-form').hidden=true;
showStep(1,false);
$('conflict-demo').onclick=()=>{products=original.map((p,i)=>i?{...p}:{...p,[goalDefinitions[story.goal].field]:null,conflicting:[story.goal],warning:'Scenario: '+goalDefinitions[story.goal].label+' conflicts across sources; excluded from that goal.'});render();};
fetch(new URLSearchParams(location.search).get('qa')==='data-error'?'unavailable-fixtures.json':'fixtures.json?v=inline8',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('load');return r.json();}).then(data=>{original=data.products.filter(p=>p.category===story.category);products=original.map(p=>({...p}));$('brand-options').innerHTML='<legend>Brands</legend>'+[...new Set(original.map(p=>p.brand))].map(b=>`<label><input type="checkbox" class="brand-filter" value="${original.filter(p=>p.brand===b).map(p=>p.id).join(',')}">${esc(b)}</label>`).join('');document.querySelectorAll('.brand-filter').forEach(i=>i.onchange=render);example();}).catch(()=>{$('result-count').textContent='Demo data unavailable';$('products').innerHTML='<p role="alert">The verified examples could not load. <a href="?story=' + storyKey + '">Return to the demo to retry.</a></p>';});

}

if(!story){$('search-form').hidden=true;document.querySelector('.skip').href='#landing';document.querySelector('.header-link').href='?story=protein#evidence';}
